declare(strict_types=1);require_once __DIR__.'/../includes/auth.php';require_once __DIR__.'/_helper.php';perpus_require_access();perpus_sync_members($pdo);$manage=perpus_can_manage();$id=(int)($_GET['id']??$_POST['id']??0);$error='';$flash=perpus_flash();
if($_SERVER['REQUEST_METHOD']==='POST'&&$manage){require_valid_csrf();$action=$_POST['action']??'save';if($action==='delete'){$st=$pdo->prepare('SELECT COUNT(*) FROM perpustakaan_peminjaman WHERE anggota_id=?');$st->execute([$id]);if((int)$st->fetchColumn()>0)$error='Anggota sudah memiliki riwayat peminjaman dan tidak dapat dihapus. Nonaktifkan saja.';else{$pdo->prepare('DELETE FROM perpustakaan_anggota WHERE id=?')->execute([$id]);perpus_audit($pdo,'DELETE',$id,'Menghapus anggota perpustakaan');perpus_flash('Anggota dihapus.');redirect('perpustakaan/anggota.php');}}elseif($action==='toggle'){$pdo->prepare("UPDATE perpustakaan_anggota SET status=IF(status='aktif','nonaktif','aktif') WHERE id=?")->execute([$id]);perpus_audit($pdo,'UPDATE',$id,'Mengubah status anggota perpustakaan');perpus_flash('Status anggota diperbarui.');redirect('perpustakaan/anggota.php');}else{$jenis=(string)($_POST['jenis']??'siswa');$ref=(int)($_POST['ref_id']??0);$kode=trim((string)($_POST['kode_anggota']??''));$tgl=(string)($_POST['tanggal_daftar']??date('Y-m-d'));$status=(string)($_POST['status']??'aktif');$ket=trim((string)($_POST['keterangan']??''));if(!in_array($jenis,['siswa','guru'],true)||$ref<=0||$kode===''||$tgl===''||!in_array($status,['aktif','nonaktif'],true))$error='Data anggota belum lengkap.';else{try{if($jenis==='siswa'){$cek=$pdo->prepare('SELECT id FROM siswa WHERE id=?');$cek->execute([$ref]);}else{$cek=$pdo->prepare('SELECT id FROM guru WHERE id=?');$cek->execute([$ref]);}if(!$cek->fetchColumn())$error='Data siswa/guru tidak ditemukan.';else{if($id){$pdo->prepare('UPDATE perpustakaan_anggota SET kode_anggota=?,siswa_id=?,guru_id=?,tanggal_daftar=?,status=?,keterangan=? WHERE id=?')->execute([$kode,$jenis==='siswa'?$ref:null,$jenis==='guru'?$ref:null,$tgl,$status,$ket?:null,$id]);perpus_audit($pdo,'UPDATE',$id,'Mengubah anggota perpustakaan');perpus_flash('Anggota diperbarui.');}else{$st=$pdo->prepare('INSERT INTO perpustakaan_anggota(kode_anggota,siswa_id,guru_id,tanggal_daftar,status,keterangan) VALUES(?,?,?,?,?,?)');$st->execute([$kode,$jenis==='siswa'?$ref:null,$jenis==='guru'?$ref:null,$tgl,$status,$ket?:null]);$new=(int)$pdo->lastInsertId();perpus_audit($pdo,'CREATE',$new,'Menambah anggota perpustakaan');perpus_flash('Anggota ditambahkan.');}redirect('perpustakaan/anggota.php');}}catch(PDOException $e){$error='Kode anggota atau siswa/guru tersebut sudah terdaftar.';}}}}
$q=trim((string)($_GET['q']??''));$statusFilter=(string)($_GET['status']??'');$where=[];$params=[];if($q!==''){$where[]='(a.kode_anggota LIKE ? OR s.nama LIKE ? OR s.nis LIKE ? OR s.nisn LIKE ? OR g.nama LIKE ? OR g.nip LIKE ?)';$like="%$q%";$params=[$like,$like,$like,$like,$like,$like];}if(in_array($statusFilter,['aktif','nonaktif'],true)){$where[]='a.status=?';$params[]=$statusFilter;}$st=$pdo->prepare('SELECT a.*,COALESCE(s.nama,g.nama) nama,s.nis,s.nisn,g.nip,CASE WHEN a.siswa_id IS NOT NULL THEN "Siswa" ELSE "Guru" END jenis FROM perpustakaan_anggota a LEFT JOIN siswa s ON s.id=a.siswa_id LEFT JOIN guru g ON g.id=a.guru_id'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY nama');$st->execute($params);$rows=$st->fetchAll();$current=$id?null:['kode_anggota'=>'','tanggal_daftar'=>date('Y-m-d'),'status'=>'aktif','keterangan'=>'','jenis'=>'siswa','ref_id'=>0];if($id){$current=perpus_member($pdo,$id);if(!$current)exit('Anggota tidak ditemukan.');$current['jenis']=$current['siswa_id']?'siswa':'guru';$current['ref_id']=(int)($current['siswa_id']?:$current['guru_id']);}
$page_title='Anggota Perpustakaan';require_once __DIR__.'/../layouts/header.php';require_once __DIR__.'/../layouts/sidebar.php';?><main class="main perpus-page"><header class="topbar"><div class="topbar-title">Anggota Perpustakaan</div><div class="topbar-user"><?=e(user_name())?></div></header><section class="content"><div class="page-header"><div><h1><i class="bi bi-people-fill"></i> Anggota</h1><p>Semua siswa dan guru aktif otomatis menjadi anggota perpustakaan. Data di halaman ini dapat digunakan untuk melihat dan mengelola status anggota; status nonaktif tetap dihormati sebagai pengecualian.</p></div><a class="btn btn-secondary" href="<?=BASE_URL?>perpustakaan/index.php"><i class="bi bi-arrow-left"></i> Kembali</a></div><?php if($flash):?><div class="alert alert-success"><?=e($flash)?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><div class="form-card"><form method="get" class="form-grid"><div class="form-group"><label>Pencarian</label><input class="form-control" name="q" value="<?=e($q)?>" placeholder="Nama, NIS, NIP, kode anggota"></div><div class="form-group"><label>Status</label><select class="form-control" name="status"><option value="">Semua</option><option value="aktif" <?=$statusFilter==='aktif'?'selected':''?>>Aktif</option><option value="nonaktif" <?=$statusFilter==='nonaktif'?'selected':''?>>Nonaktif</option></select></div><div class="form-actions"><button class="btn btn-primary"><i class="bi bi-search"></i> Cari</button></div></form></div><?php if($manage):?><div class="form-card"><h5><?= $id?'Edit':'Tambah' ?> Anggota</h5><form method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=$id?>"><div class="form-grid"><div class="form-group"><label>Jenis *</label><select class="form-control" name="jenis" id="jenis"><option value="siswa" <?=$current['jenis']==='siswa'?'selected':''?>>Siswa</option><option value="guru" <?=$current['jenis']==='guru'?'selected':''?>>Guru</option></select></div><div class="form-group form-group-full"><label>Cari Siswa/Guru *</label><input class="form-control" id="memberSearch" autocomplete="off" placeholder="Ketik minimal 2 karakter: nama, NIS, NIP..." value=""><input type="hidden" name="ref_id" id="refId" value="<?=e($current['ref_id'])?>"><div id="memberResults" class="search-results"></div><div id="selectedMember" class="selected-result"></div></div><div class="form-group"><label>Kode Anggota *</label><input class="form-control" name="kode_anggota" value="<?=e($current['kode_anggota'])?>" required></div><div class="form-group"><label>Tanggal Daftar</label><input class="form-control" type="date" name="tanggal_daftar" value="<?=e($current['tanggal_daftar'])?>" required></div><div class="form-group"><label>Status</label><select class="form-control" name="status"><option value="aktif" <?=$current['status']==='aktif'?'selected':''?>>Aktif</option><option value="nonaktif" <?=$current['status']==='nonaktif'?'selected':''?>>Nonaktif</option></select></div><div class="form-group"><label>Keterangan</label><input class="form-control" name="keterangan" value="<?=e($current['keterangan']??'')?>"></div></div><div class="form-actions"><button class="btn btn-primary"><i class="bi bi-save"></i> Simpan</button><?php if($id):?><a class="btn btn-secondary" href="<?=BASE_URL?>perpustakaan/anggota.php">Batal</a><?php endif;?></div></form></div><?php endif;?><div class="form-card"><div class="table-responsive"><table class="data-table"><thead><tr><th>Kode</th><th>Nama</th><th>Jenis</th><th>Tanggal Daftar</th><th>Status</th><?php if($manage):?><th>Aksi</th><?php endif;?></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="6" class="empty-state">Belum ada anggota.</td></tr><?php else:foreach($rows as $r):?><tr><td><?=e($r['kode_anggota'])?></td><td><strong><?=e($r['nama']??'-')?></strong><div class="text-muted small"><?=e($r['nis']??$r['nip']??'')?></div></td><td><?=e($r['jenis'])?></td><td><?=e($r['tanggal_daftar'])?></td><td><?= $r['status']==='aktif'?'<span class="badge bg-success">Aktif</span>':'<span class="badge bg-secondary">Nonaktif</span>' ?></td><?php if($manage):?><td style="white-space:nowrap"><a class="btn btn-sm btn-primary btn-icon-sm" href="?id=<?=$r['id']?>" title="Edit anggota" aria-label="Edit anggota"><i class="bi bi-pencil-square" aria-hidden="true"></i></a><form method="post" class="d-inline"><?=csrf_field()?><input type="hidden" name="id" value="<?=$r['id']?>"><input type="hidden" name="action" value="toggle"><button class="btn btn-sm btn-secondary" title="Aktif/nonaktif"><i class="bi bi-toggle-on"></i></button></form><form method="post" class="d-inline" onsubmit="return confirm('Hapus anggota?')"><?=csrf_field()?><input type="hidden" name="id" value="<?=$r['id']?>"><input type="hidden" name="action" value="delete"><button class="btn btn-sm btn-danger" title="Hapus anggota" aria-label="Hapus anggota"><i class="bi bi-trash"></i></button></form></td><?php endif;?></tr><?php endforeach;endif;?></tbody></table></div></div></section></main><script>document.addEventListener('DOMContentLoaded',()=>{const q=document.getElementById('memberSearch'),rid=document.getElementById('refId'),box=document.getElementById('memberResults'),sel=document.getElementById('selectedMember'),type=document.getElementById('jenis');if(!q)return;let t;const render=(rows)=>{box.innerHTML='';rows.forEach(r=>{const b=document.createElement('button');b.type='button';b.className='list-group-item list-group-item-action';b.textContent=r.nama+' · '+(r.nis||r.nip||r.kode_anggota);b.onclick=()=>{rid.value=r.id;q.value=r.nama;box.innerHTML='';sel.innerHTML='<span class="badge bg-primary">Terpilih: '+r.nama+' · '+r.kode_anggota+'</span>';};box.appendChild(b);});};q.addEventListener('input',()=>{clearTimeout(t);const v=q.value.trim();if(v.length<2){box.innerHTML='';return;}t=setTimeout(()=>fetch('api.php?type=anggota&q='+encodeURIComponent(v)).then(r=>r.json()).then(x=>render(x.data||[])),250);});type.addEventListener('change',()=>{rid.value='';q.value='';box.innerHTML='';sel.innerHTML='';});});</script><style>.search-results{margin-top:4px;position:relative;z-index:10}.search-results button{display:block;width:100%;text-align:left}.selected-result{margin-top:8px}</style><?php require_once __DIR__.'/../layouts/footer.php';
